def compute(vars):
    lease_obligations = vars["v1"]
    total_obligations = vars["v2"]

    if total_obligations == 0:
        return None

    value = lease_obligations / total_obligations * 100
    return {
        "value": value,
        "trace": {
            "lease_obligations": lease_obligations,
            "total_obligations": total_obligations,
            "ratio": lease_obligations / total_obligations,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
